package com.smritisathi.app.auth;
import android.os.*;import android.widget.*;import android.content.*;import com.google.gson.*;import com.smritisathi.app.core.*;
public class RegisterActivity extends BaseActivity {EditText name,age,phone,password,email;Spinner role,lang; @Override public void onCreate(Bundle b){super.onCreate(b);header("Create account");name=UI.edit(this,"Full name");age=UI.edit(this,"Age");phone=UI.edit(this,"Phone");password=UI.edit(this,"Password");email=UI.edit(this,"Email (optional)");root.addView(name);root.addView(age);root.addView(phone);root.addView(password);root.addView(email);role=new Spinner(this);role.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"patient","caregiver"}));root.addView(role);lang=new Spinner(this);lang.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"english","assamese"}));root.addView(lang);Button btt=UI.button(this,"Register");root.addView(btt);btt.setOnClickListener(v->register());}void register(){if(name.getText().length()==0||age.getText().length()==0||phone.getText().length()==0||password.getText().length()==0){UI.toast(this,"Please fill required fields");return;}JsonObject b=ApiClient.obj("name",name.getText().toString(),"age",age.getText().toString(),"role",role.getSelectedItem().toString(),"phone",phone.getText().toString(),"password",password.getText().toString(),"email",email.getText().toString(),"preferredLanguage",lang.getSelectedItem().toString(),"region","NER");ApiClient.request("POST","/auth/register",null,b,(ok,d,e)->{if(!ok){UI.toast(this,e);return;}JsonObject u=d.getAsJsonObject("user");Session.save(this,d.get("token").getAsString(),u.get("role").getAsString(),u.get("_id").getAsString(),u.get("name").getAsString(),u.has("preferredLanguage")?u.get("preferredLanguage").getAsString():"english");UI.toast(this,"Registration successful");finish();});}}
